// 2026-02-14 Generated by IBM Bob
// List all container images in specified repositories from local registry
// Uses Docker Registry V2 API (no authentication required)

def call(Map parameters) {
    // Get parameters
    def registryUrl = parameters.get("registryUrl", "http://registry.qe.ceph.lab:5000")
    def repositories = parameters.get("repositories", ["rh-stage", "ibm-stage"])

    echo "=== Querying Registry for Images ==="
    echo "Registry URL: ${registryUrl}"
    echo "Target Repositories: ${repositories.join(', ')}"

    def allImages = [:]
    repositories.each { repoPrefix ->
        allImages[repoPrefix] = []
    }

    try {
        // Step 1: Get catalog of all repositories
        echo "\nFetching repository catalog..."
        def catalogUrl = "${registryUrl}/v2/_catalog"
        def catalogJson = sh(
            script: "curl -s ${catalogUrl}",
            returnStdout: true
        ).trim()

        def catalog = readJSON text: catalogJson
        def allRepos = catalog.repositories ?: []

        echo "Total repositories in registry: ${allRepos.size()}"

        // Step 2: Filter repositories by prefix
        def filteredRepos = []
        repositories.each { repoPrefix ->
            def matching = allRepos.findAll { it.startsWith("${repoPrefix}/") }
            filteredRepos.addAll(matching)
            echo "  - ${repoPrefix}: ${matching.size()} repositories"
        }

        if (filteredRepos.isEmpty()) {
            echo "No repositories found matching prefixes: ${repositories.join(', ')}"
            return allImages
        }

        echo "\nQuerying tags for ${filteredRepos.size()} repositories..."

        // Step 3: Get tags for each repository
        filteredRepos.each { repo ->
            try {
                def tagsUrl = "${registryUrl}/v2/${repo}/tags/list"
                def tagsJson = sh(
                    script: "curl -s ${tagsUrl}",
                    returnStdout: true
                ).trim()

                def tagsData = readJSON text: tagsJson
                def tags = tagsData.tags ?: []

                if (tags.size() > 0) {
                    // Determine which prefix this repo belongs to
                    def repoPrefix = repositories.find { repo.startsWith("${it}/") }

                    // Build full image URLs
                    tags.each { tag ->
                        def fullImage = "${repo}:${tag}"
                        allImages[repoPrefix] << fullImage
                    }

                    echo "  ✓ ${repo}: ${tags.size()} tags"
                }
            } catch (Exception e) {
                echo "  ✗ Error querying ${repo}: ${e.getMessage()}"
            }
        }

        // Summary
        echo "\n=== Registry Query Summary ==="
        def totalImages = 0
        repositories.each { repoPrefix ->
            def count = allImages[repoPrefix].size()
            totalImages += count
            echo "  - ${repoPrefix}: ${count} images"
        }
        echo "  Total images: ${totalImages}"
        echo "=============================="

    } catch (Exception e) {
        echo "Error querying registry: ${e.getMessage()}"
        throw e
    }

    return allImages
}
